import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.CHeM0PsO.js";const P=JSON.parse('{"title":"页面与 Play","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/pages-play.md","filePath":"guide/misskey/pages-play.md","lastUpdated":1789295632000}'),r={name:"guide/misskey/pages-play.md"};function s(p,a,o,c,d,n){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="页面与-play" tabindex="-1">页面与 Play <a class="header-anchor" href="#页面与-play" aria-label="Permalink to &quot;页面与 Play&quot;">​</a></h1><p>两者都是「创建内容页」的工具：页面偏静态图文，Play 偏互动程序。</p><h2 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to &quot;页面&quot;">​</a></h2><p>页面（Pages）用于创建独立的图文页面，适合发布长文、教程、设定集等：</p><ul><li>通过侧栏「页面」进入，点击「创建页面」。</li><li>编辑器支持分块组织内容：正文区块、图片区块、便签引用等。</li><li>页面有独立 URL，可分享给任何人。</li><li>可以给页面设置标题、摘要、封面图、敏感标记。</li><li>发布后可随时编辑，也支持查看源代码。</li></ul><p>与帖子的区别：帖子是时间线动态，页面是长期存在的独立文章，适合置顶链接分享。</p><h2 id="play" tabindex="-1">Play <a class="header-anchor" href="#play" aria-label="Permalink to &quot;Play&quot;">​</a></h2><p>Play 是用 AiScript 脚本语言编写的互动小程序，可以做出按钮、小测试、抽签、计算器等交互内容：</p><ul><li>通过侧栏「Play」进入，可浏览热门 Play、管理自己的 Play。</li><li>点击「创建 Play」后编写脚本，设置标题、描述、封面。</li><li>可以标记喜欢其他用户的 Play。</li><li>Play 同样有独立 URL，可分享。</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Play 使用 Misskey 内置的 AiScript 语言，官方文档与社区有大量示例可参考。想深入学习可以查阅 <a href="https://github.com/aiscript-dev/aiscript" target="_blank" rel="noreferrer">AiScript 官方仓库</a>。</p></div>',10)])])}const _=l(r,[["render",s]]);export{P as __pageData,_ as default};
